const puppeteer = require('puppeteer-core');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium',
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--force-device-scale-factor=1']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1200, height: 1000, deviceScaleFactor: 1 });
  const file = 'file://' + path.resolve('/workspace/AI 工作区/成果文件/学习附件，给我做一个一图看懂太空算力-conv_da7d6a0140d5/太空算力长图.html');
  await page.goto(file, { waitUntil: 'networkidle0', timeout: 60000 });
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 800));
  const h = await page.evaluate(() => document.body.scrollHeight);
  console.log('page height:', h);
  await page.setViewport({ width: 1200, height: h, deviceScaleFactor: 2 });
  await new Promise(r => setTimeout(r, 500));
  const out = '/workspace/AI 工作区/成果文件/学习附件，给我做一个一图看懂太空算力-conv_da7d6a0140d5/一张图看懂太空算力.png';
  await page.screenshot({ path: out, fullPage: true });
  console.log('saved:', out);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

